static void safe_unlink(chunk_t *prev, chunk_t *next) {
    if (!prev || !next) return;               // defensive null checks

    /* Detect cycles: if next is already reachable from prev we have a loop */
    if (next == prev) {
        fprintf(stderr, "Cycle detected – aborting unlink\n");
        return;                               // abort to avoid corruption
    }

