int main(void) {
    /* Disable tcache for allocations up to 64 bytes */
    const char *name = "tcache_max_small_alloc";
    const char *value = "64";   // limit to 64 bytes per thread cache
    if (mallctl(name, NULL, NULL, value, strlen(value)) != 0) {
        perror("mallctl");
        return 1;
    }

    /* Allocate a buffer that will later be used as a fake chunk */
    char *buf = malloc(0x100);
