#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>

/* Global flag set by the SIGINT handler */
static volatile sig_atomic_t stop = 0;

/* Worker thread – runs concurrently with the main thread */
static void *worker(void *arg)
{
    for (volatile int i = 0; i < 1000; ++i) {
        /* No blocking calls – just keep the CPU busy */
        asm volatile("" ::: "memory");
    }
    return NULL;
}

/* SIGINT handler – unsafe because it calls printf (non‑async‑signal‑safe) */
static void sigint_handler(int signo)
{
    printf("[SIGINT] caught, printing message\n");
    /* The call to printf may be interrupted by another signal or by another thread entering printf,
       leading to interleaved output or corrupted internal state (race condition). */
}

/* Corrected SIGINT handler – only async‑signal‑safe operations */
static void sigint_handler_fixed(int signo)
{
    /* Use write() which is async‑signal‑safe; it writes directly to the file descriptor without locking.
       We also set a flag atomically so that any other thread can observe it safely. */
    write(STDOUT_FILENO, "[SIGINT] caught, writing atomically\n", 38);
    /* Use atomic store to avoid data races on multi‑threaded programs */
    atomic_store(&stop, 1);
}

/* Thread function that will be interrupted by SIGALRM (mapped to SIGALRM via alarm()) */
static void *thread(void *arg)
{
    for (volatile int i = 0; i < 1000; ++i) {
        /* No blocking calls – just keep the CPU busy */
        asm volatile("" ::: "memory");
    }
    return NULL;
}

int main(void)
{
    pthread_t th;
    int rc;

    /* Install safe SIGINT handler */
    struct sigaction sa = {0};
    sa.sa_handler = sigint_handler_fixed;
    sa.sa_flags = SA_RESTART;   // ignore EINTR for simplicity
    rc = sigaction(SIGINT, &sa, NULL);
