    /* Give the worker a chance to start and possibly enter printf */
    usleep(1000); // 1 ms – enough for the worker to be scheduled once

    /* Raise SIGINT while the worker is inside printf (or any other async‑signal‑safe function).
       We replace SIGALRM with SIGALRM via alarm(). */

    alarm(1); // fire after 1 second – this will send SIGALRM which we map to SIGALRM handling.

    /* Wait for the worker to finish */
    rc = pthread_join(th, NULL);

    if (stop) {
        printf("[RESULT] Race condition detected: %d\n", stop);
        return EXIT_SUCCESS;
