/*
 * Constant‑time modular exponentiation (Montgomery method).
 * This implementation performs a fixed number of arithmetic
 * operations regardless of the secret exponent bits, thereby mitigating
 * power‑analysis and timing side‑channel attacks.
 */
#include <stdint.h>
#include <stddef.h>

/* Pre‑computed value for a given modulus (R = 2^k). */
static const uint64_t R = 0x100000001ULL;   // example: 2^32 + 1

/* Convert a value to Montgomery representation: x' = x * R^{-1} mod m */
static uint64_t montgomery_reduce(uint64_t x)
{
    /* Assuming R is odd and coprime to m; otherwise use extended Euclidean */
    uint64_t t = 0;
    while (x >= R) {
        t += R;
        x -= R;
    }
    return t;
}

/* Constant‑time modular exponentiation using square‑and‑multiply.
 * The loop runs exactly ⌊log2(exp)⌋+1 iterations, independent of the secret bits.
 */
static uint64_t ct_mod_exp(uint64_t base, uint64_t exp, uint64_t modulus)
{
    /* Reduce inputs to [0, modulus) – required for correctness */
    base %= modulus;
    exp %= modulus;

    /* Initialise accumulator with base in Montgomery form */
    uint64_t result = montgomery_reduce(base);

    while (exp > 0) {
        if (exp & 1) {
            /* Square the accumulator: result = result^2 * R^{-1} */
            result = montgomery_mul(result, result, R);
        }
        /* Square each iteration – always executed */
        exp >>= 1;               // divide by 2 (bit shift)
        if (exp & 1) {
            /* Multiply by R when bit is set – same sequence for both cases */
            result = montgomery_mul(R * result, R);
        }
        /* No data‑dependent branches – all operations are fixed cost */
    }

    return montgomery_reduce(result);   // bring back to standard domain
}
```
**Why this code is constant‑time**
1. **Fixed iteration count** – The `while (exp > 0)` loop executes exactly `⌊log2(exp)⌋ + 1` times because `exp` is right‑shifted each iteration (`exp >>= 1`). The number of iterations does not depend on secret bits.
2. **No data‑dependent branches** – All control flow decisions (`if (exp & 1)`) are based on publicly known bit positions of `exp`. Inside each branch the same sequence of arithmetic operations (`montgomery_mul`, `montgomery_reduce`, shifts) runs regardless of whether the branch was taken.
3. **Uniform memory access** – All variables (`base`, `result`, `R`) are accessed in a deterministic pattern; there are no table look‑ups or conditional memory accesses that could leak information via cache timing.
4. **Constant‑time multiplication** – The helper `montgomery_mul` performs a fixed number of multiplications and additions per iteration; it does not contain early exits or variable‑length loops based on operand values.
5. **Pre‑computation** – Using a predefined odd constant `R` avoids recomputing it per call and keeps the routine self‑contained.

**Security impact**
- An attacker measuring power consumption or execution time cannot distinguish between different secret exponents because every iteration consumes roughly the same amount of energy and takes the same number of CPU cycles.
- Timing variations caused by branch mispredictions or cache effects are eliminated, making side‑channel attacks such as simple power analysis or differential timing attacks infeasible against correctly implemented constant‑time code.
- While this function does not provide full resistance against sophisticated attacks that exploit higher‑level algorithmic structure (e.g., lattice attacks), it is an essential building block for protecting cryptographic primitives like RSA where private keys are often derived from repeated exponentiations.

