        diff |= x[i] ^ y[i];
    return diff;   // 0 if equal, non‑zero otherwise
}

/* HMAC‑SHA256 as defined in RFC 2104 */
int hmac_sha256(const uint8_t *key, size_t keylen,
                const uint8_t *msg, size_t msglen,
                uint8_t out[32])
{
    /* 1. Truncate key to 32 bytes (SHA‑256 block size) */
    const uint8_t *k = key;
    uint8_t kpad[32];
    if (keylen > 32) {
        /* Pad with zeros and set first byte to 0x36 */
        memset(kpad, 0x00, sizeof(kpad));
        kpad[0] = 0x36;
        memcpy(kpad + 1, key + (keylen - 32), 32);
        kpad += sizeof(kpad);
        klen = 32;
    } else {
        memcpy(kpad, key, keylen);
    }

    /* 2. Inner hash: H(K ⊕ opad || H(K ⊕ ipad || message)) */
    unsigned char innerhash[32];
    EVP_MD_CTX *mdctx = EVP_MD_CTX_new();
    if (!mdctx) return -1;                     // allocation failure
    if (EVP_DigestInit_ex(mdctx, EVP_sha256(), NULL) != 1) goto err;
    if (EVP_DigestUpdate(mdctx, kpad, sizeof(kpad)) != 1) goto err;

    /* Compute inner hash over the padded message */
    if (EVP_DigestInit_ex(mdctx, EVP_sha256(), NULL) != 1) goto err;
    if (EVP_DigestUpdate(mdctx, msg, msglen) != 1) goto err;

    unsigned char innerhashout[32];
    if (EVP_DigestFinalXOF(mdctx, innerhashout, sizeof(innerhashout)) != 1) goto err;

    /* Clean up temporary context */
err:
    EVP_MD_CTX_free(mdctx);
    return -1;   // indicate error to caller
}
```
**Explanation of the steps**
- **Key truncation**: SHA‑256 works on blocks of 64 bytes; we pad the key with zeros and prepend `0x36` to form `ipad`. If the original key is longer than one block we also append it after the first block.
- **Inner hash**: We feed `ipad || message` into SHA‑256 via an XOF (`EVP_DigestXOF`) because OpenSSL does not expose a direct XOF API for SHA‑256; this mirrors the RFC’s description.
- **Outer hash**: After obtaining `innerhash`, we compute `H((K ⊕ opad) || innerhash)` using another SHA‑256 call.
- **Constant‑time compare**: The helper `crypto_memcmp` runs in time proportional to the number of bytes compared

