/*
 * i2c-eeprom-reader.c – Read an EEPROM attached to an I2C bus
 *
 * This program opens a Linux I2C character device (e.g., /dev/i2c-1),
 * reads the EEPROM at address 0x50 using SMBus byte‑read, and prints the
 * 8‑byte serial key.
 */

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

/* SMBus helper prototypes – these are provided by libi2c-dev on most distros */
extern int i2c_smbus_read_byte(int file, uint8_t addr);
extern int i2c_smbus_read_word(int file, uint8_t addr);
extern int i2c_smbus_read(int file, uint8_t addr);

int main(void)
{
    const char *dev = "/dev/i2c-1";   /* adjust to your bus */
    int fd;
    uint8_t eeprom[8];
    int ret;

    if (access(dev, R_OK) != 0) {
        fprintf(stderr, "Device %s not accessible\n", dev);
        return EXIT_FAILURE;
    }

    fd = open(dev, O_RDONLY);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    /* Read the first byte – usually the manufacturer ID */
    ret = i2c_smbus_read(fd, 0x50);   /* address from datasheet */
    if (ret < 0) {
        fprintf(stderr, "SMBus read failed: %s\n", strerror(-ret));
        close(fd);
        return EXIT_FAILURE;
    }
    printf("Manufacturer ID: %02x\n", ret);

    /* Read the remaining 7 bytes as a little‑endian word */
    ret = i2c_smbus_read(fd, 0x51);   /* second byte of EEPROM */
    if (ret < 0) {
        fprintf(stderr, "SMBus read failed: %s\n", strerror(-ret));
        close(fd);
        return EXIT_FAILURE;
    }
    memcpy(&eeprom[1], &ret + 1, sizeof(uint8_t)); /* skip first byte */

    printf("Serial Key: ");
    for (int i = 0; i < sizeof(eeprom); ++i)
        printf("%02x", eeprom[i]);
    printf("\n");

    close(fd);
    return EXIT_SUCCESS;
}
